cat > test-threshold.mjs << 'EOF'
import { Command } from 'commander';

const program = new Command();

program
  .command('eval')
  .option('--threshold <value>', 'Threshold value')
  .action((options) => {
    console.log('typeof threshold:', typeof options.threshold);
    console.log('threshold:', options.threshold);
    console.log('JSON:', JSON.stringify(options.threshold));
  });

program.parseAsync(['node', 'test', 'eval', '--threshold', 'exact_match=0.8']);
EOF
node test-threshold.mjs
